head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.TARGETS = ["target1", "target2", "target3"];

// 대상 컴포넌트의 display / visibility / aria-hidden 을 한 줄로 출력
scwin.printState = function (strPrefix) {
    for (var i = 0; i < scwin.TARGETS.length; i++) {
        var strId = scwin.TARGETS[i];
        var objComp = $p.getComponentById(strId);
        var objRender = objComp.render;
        var objStyle = window.getComputedStyle(objRender);

        scwin.setReturnValue(strPrefix + " " + strId
            + "  display : " + objStyle.display
            + "  visibility : " + objStyle.visibility
            + "  aria-hidden : " + objRender.getAttribute("aria-hidden"));
    }
};

scwin.btn_hide_onclick = function (e) {
    for (var i = 0; i < scwin.TARGETS.length; i++) {
        $p.getComponentById(scwin.TARGETS[i]).hide();
    }
    scwin.printState("[hide()]");
};

scwin.btn_show_onclick = function (e) {
    for (var i = 0; i < scwin.TARGETS.length; i++) {
        $p.getComponentById(scwin.TARGETS[i]).show();
    }
    scwin.printState("[show()]");
};
